// iOS Safari does not fire :active on <a> taps without a touch listener present.
document.querySelectorAll('.btn').forEach(function (btn) {
  btn.addEventListener('touchstart', function () {}, { passive: true });
});

// Render the searchable individual-contact list from assets/contacts-data.js
// (window.FELLOWSHIP_CONTACTS, generated by tools/build_vcf.py from the CSV).
(function () {
  var list = document.getElementById('contactList');
  var empty = document.getElementById('contactEmpty');
  var search = document.getElementById('contactSearch');
  var contacts = window.FELLOWSHIP_CONTACTS || [];
  if (!list || !contacts.length) return;

  var rows = contacts.map(function (c) {
    var li = document.createElement('li');
    li.className = 'contact-row';

    var name = document.createElement('span');
    name.className = 'contact-name';
    name.textContent = c.name;

    var link = document.createElement('a');
    link.className = 'btn-row';
    link.href = c.file;
    link.setAttribute('download', c.name + '.vcf');
    link.innerHTML = '<svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">' +
      '<path d="M12 3v10m0 0 3.5-3.5M12 13 8.5 9.5M5 17.5h14" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>' +
      '</svg><span>إضافة إلى جهات الاتصال</span>';
    link.addEventListener('touchstart', function () {}, { passive: true });

    li.appendChild(name);
    li.appendChild(link);
    list.appendChild(li);
    return { el: li, name: c.name };
  });

  if (!search) return;
  search.addEventListener('input', function () {
    var q = search.value.trim();
    var visibleCount = 0;
    rows.forEach(function (row) {
      var match = q === '' || row.name.indexOf(q) !== -1;
      // .contact-row sets its own `display: flex`, which (per the CSS
      // cascade) overrides the UA stylesheet's `[hidden]{display:none}`
      // rule even though `.hidden` still gets set correctly -- so toggle
      // display directly instead of relying on the `hidden` IDL property.
      row.el.style.display = match ? '' : 'none';
      if (match) visibleCount++;
    });
    empty.hidden = visibleCount !== 0;
  });
})();
